-- 艾宾浩斯单词背诵学习系统词库导入脚本
-- 说明：原始词库只有英文单词和中文释义，没有英标数据。
-- 因此本脚本导入 word.phonetic 时统一写入空字符串 ''。
-- 使用方式：先执行 backend/src/main/resources/db/schema.sql，再执行本文件。

USE `ebbinghaus_vocab`;
SET NAMES utf8mb4;
SET FOREIGN_KEY_CHECKS = 0;

-- 初中英语核心词库: 1987 words
INSERT INTO `word_book` (`user_id`, `name`, `category`, `description`, `word_count`, `type`, `status`)
SELECT NULL, '初中英语核心词库', '初中', '适合初中英语学习的基础核心词汇', 0, 1, 1
WHERE NOT EXISTS (SELECT 1 FROM `word_book` WHERE `name` = '初中英语核心词库' AND `type` = 1 AND `deleted` = 0);

SET @book_id := (SELECT `id` FROM `word_book` WHERE `name` = '初中英语核心词库' AND `type` = 1 AND `deleted` = 0 ORDER BY `id` LIMIT 1);

INSERT INTO `word` (`book_id`, `spelling`, `phonetic`, `part_of_speech`, `meaning`, `example_sentence`, `example_translation`, `difficulty`, `status`)
